// Exercise unlock_stream with both NULL and a valid, writable stream.
// 1) NULL is explicitly allowed and should be a no-op.
unlock_stream((FILE *)0);

// 2) Create a temporary writable file and pass its FILE*.
//    We ensure mode is writable so unlocking can be attempted without error.
const char *fname = FUZZ_PARAM_FILENAME();
const char *modes[] = {"w", "w+", "a", "a+", "wb", "wb+", "ab", "ab+"};
unsigned int midx = *FUZZ_PARAM(unsigned int) % (sizeof(modes)/sizeof(modes[0]));
FILE *f = fopen(fname, modes[midx]);
if (f) {
  unlock_stream(f);
  // Close to avoid fd leaks.
  fclose(f);
} // If fopen failed, we did exercise the NULL path above already.

// Open a file with a valid mode, then immediately close it to avoid leaks.
const char *path = FUZZ_PARAM_FILENAME();
// Constrain mode to typical valid fopen modes.
const char *modes[] = {"r", "rb", "r+", "rb+", "w", "wb", "w+", "wb+", "a", "ab", "a+", "ab+"};
unsigned int mi = *FUZZ_PARAM(unsigned int) % (sizeof(modes)/sizeof(modes[0]));
FILE *fp = fopen_unlocked(path, modes[mi]);
if (fp) {
  // If open succeeded, we must close it.
  fclose(fp);
} // else: expected on incompatible mode/path; no further action.

// Create a valid file descriptor using mkstemps and then wrap it via fdopen_unlocked.
// Build a writable template ending with three Xs and a suffix of length 3.
const char *base = choose_tmpdir();
std::string templ = std::string(base) + "/fuzzfdXXXXXX.suf"; // suffix length 3
std::vector<char> buf(templ.begin(), templ.end());
buf.push_back('\0');
int fd = mkstemps(buf.data(), 3);
if (fd >= 0) {
  // Pick a mode compatible with an existing read/write descriptor.
  const char *modes[] = {"r+", "rb+", "w+", "wb+", "a+", "ab+"};
  unsigned int mi = *FUZZ_PARAM(unsigned int) % (sizeof(modes)/sizeof(modes[0]));
  FILE *fp = fdopen_unlocked(fd, modes[mi]);
  if (fp) {
    fclose(fp); // closes the underlying fd as well
  } else {
    // Best-effort cleanup if wrapping failed: try standard fdopen then fclose.
    FILE *tmp = fdopen(fd, "r");
    if (tmp) {
      fclose(tmp);
    }
    // If even fdopen failed, we may leak the fd on some platforms; acceptable in fuzz context.
  }
} else {
  // Exercise error path: invalid fd should cause failure.
  FILE *fp = fdopen_unlocked(-1, "r");
  (void)fp; // Expect NULL
}

// Create a file, then freopen_unlocked it with a new mode and (possibly) new path.
const char *orig = FUZZ_PARAM_FILENAME();
FILE *fp = fopen(orig, "w+");
if (!fp) {
  FUZZ_BAIL();
}
const char *newpath = FUZZ_PARAM_FILENAME();
const char *modes[] = {"r", "r+", "w", "w+", "a", "a+", "rb", "rb+", "wb", "wb+", "ab", "ab+"};
unsigned int mi = *FUZZ_PARAM(unsigned int) % (sizeof(modes)/sizeof(modes[0]));
FILE *re = freopen_unlocked(newpath, modes[mi], fp);
if (re) {
  // On success, fclose the resulting stream.
  fclose(re);
} else {
  // On failure, the stream may be closed; attempt to close to avoid leaks if still open.
  // This is best-effort; fclose on an invalidated stream may fail harmlessly.
  fclose(fp);
}

// Build an argv vector from a fuzzy command line and return it to the pool.
std::string cmd = FUZZ_PARAM_STR();
// Ensure non-empty so at least one token is likely.
if (cmd.empty()) { cmd = "echo"; }
char **argv_vec = buildargv(cmd.c_str());
if (!argv_vec) { FUZZ_BAIL(); }
// Mark for downstream consumers (dupargv, freeargv, writeargv, countargv).
FUZZ_SET_ATTR_INT(argv_vec, "is_argv", 1);
// Provide argv_vec as an output for reuse by other stubs.

// Validate that argv_vec came from buildargv/dupargv via attribute, then free it.
if (FUZZ_GET_ATTR_INT(argv_vec, "is_argv") != 1) { FUZZ_BAIL(); }
freeargv((char **)argv_vec);
// Drop it from the pool by not returning it.

// Duplicate a NULL-terminated argv vector and return the duplicate.
if (FUZZ_GET_ATTR_INT(argv_src, "is_argv") != 1) { FUZZ_BAIL(); }
char **argv_dup = dupargv((char * const *)argv_src);
if (!argv_dup) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(argv_dup, "is_argv", 1);
// Keep both the source and the duplicate live by returning the duplicate; the source
// remains live via the fuzzer pool since we didn't free it.

// Prepare a small argv vector and call expandargv in-place, then free the result.
std::string a0 = "prog";
std::string a1 = FUZZ_PARAM_STR();
std::string a2 = FUZZ_PARAM_STR();
// Build a heap argv so the function can realloc/replace it as needed.
std::vector<char*> items;
items.push_back((char*)a0.c_str());
items.push_back((char*)a1.c_str());
items.push_back((char*)a2.c_str());
items.push_back((char*)0);
int argc = (int)items.size() - 1;
char **argv = (char**)xmemdup(items.data(), sizeof(char*) * items.size(), sizeof(char*) * items.size());
// Call expandargv; it may replace argv and update argc.
expandargv(&argc, &argv);
// Free via freeargv per API conventions.
freeargv(argv);

// Create an argv vector and a writable FILE*, then call writeargv and close.
std::string a0 = "echo";
std::string a1 = FUZZ_PARAM_STR();
char *vec_local[3];
vec_local[0] = (char*)a0.c_str();
vec_local[1] = (char*)a1.c_str();
vec_local[2] = 0;
const char *outpath = FUZZ_PARAM_FILENAME();
FILE *out = fopen(outpath, "wb");
if (!out) { FUZZ_BAIL(); }
int rc = writeargv((char * const *)vec_local, out);
// We don't assert on rc because the function may signal errors; just exercise it.
(void)rc;
fclose(out);

// Build a simple NULL-terminated argv and count it.
std::string a0 = "cmd";
std::string a1 = FUZZ_PARAM_STR();
char *vec[4];
vec[0] = (char*)a0.c_str();
vec[1] = (char*)a1.c_str();
vec[2] = (char*)"tail";
vec[3] = 0;
int n = countargv((char * const *)vec);
FUZZ_ASSERT(n >= 0, "countargv must not return negative");

// Provide a non-NULL path and call lbasename (always non-NULL).
